import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"GitHub Copilot Learning Map","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/copilot/index.md","filePath":"products/ai-coding/copilot/index.md","lastUpdated":1787046041000}'),n={name:"products/ai-coding/copilot/index.md"};function r(i,t,l,d,p,c){return a(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="github-copilot-learning-map" tabindex="-1">GitHub Copilot Learning Map <a class="header-anchor" href="#github-copilot-learning-map" aria-label="Permalink to &quot;GitHub Copilot Learning Map&quot;">​</a></h1><blockquote><p>GitHub Copilot is a family of AI coding products that share one subscription, but differ in entry point, autonomy, and side-effect radius. This page is the landscape and decision tree — <strong>name the surface first, then decide what to learn</strong>.</p></blockquote><h2 id="product-landscape" tabindex="-1">Product landscape <a class="header-anchor" href="#product-landscape" aria-label="Permalink to &quot;Product landscape&quot;">​</a></h2><p>Official feature list: <a href="https://docs.github.com/en/copilot/get-started/features" target="_blank" rel="noreferrer">GitHub Copilot features</a>. Assistive tools work <strong>with you</strong>; agentic tools can work <strong>without you watching</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GitHub Copilot</span></span>
<span class="line"><span>├── IDE — VS Code / Visual Studio / JetBrains / Xcode / Eclipse</span></span>
<span class="line"><span>│   ├── Inline suggestions (ghost text; next-edit suggestions in VS Code / Xcode / Eclipse)</span></span>
<span class="line"><span>│   └── Chat: Ask / Edit / Agent mode (Agent mode runs locally)</span></span>
<span class="line"><span>├── github.com — Web (maps to Claude&#39;s Web)</span></span>
<span class="line"><span>│   ├── Copilot Chat (https://github.com/copilot, or any repo / Issue / PR)</span></span>
<span class="line"><span>│   ├── Cloud agent — research / plan / branch / optional PR (paid plans)</span></span>
<span class="line"><span>│   ├── Code review</span></span>
<span class="line"><span>│   └── Pull request summaries</span></span>
<span class="line"><span>├── Copilot CLI — Terminal (maps to Claude&#39;s CLI)</span></span>
<span class="line"><span>│   ├── Interactive session (\`copilot\`)</span></span>
<span class="line"><span>│   └── Programmatic (\`copilot -p &quot;...&quot;\`)</span></span>
<span class="line"><span>├── Copilot app — Desktop (maps to Claude&#39;s Desktop)</span></span>
<span class="line"><span>│   └── Parallel agent sessions, Issues / PRs / scheduled automations</span></span>
<span class="line"><span>├── GitHub Mobile</span></span>
<span class="line"><span>└── GitHub Desktop — commit messages only</span></span></code></pre></div><p><strong>Do not start these.</strong> They are sunset or closing:</p><table tabindex="0"><thead><tr><th>Product</th><th>Status</th><th>What replaced it</th></tr></thead><tbody><tr><td><strong>Copilot Workspace</strong></td><td>Sunset <strong>2025-05-30</strong></td><td>Cloud agent</td></tr><tr><td><strong>GitHub App Copilot Extensions</strong></td><td>Sunset <strong>2025-11-10</strong></td><td>MCP</td></tr><tr><td><strong><code>gh copilot</code></strong></td><td>Officially <strong>retired</strong></td><td>Standalone <code>copilot</code> CLI</td></tr><tr><td><strong>GitHub Spark</strong></td><td>No new users / no new apps from <strong>2026-08-04</strong>; export existing apps by <strong>2026-08-31</strong></td><td>Build in the IDE, CLI, or Copilot app</td></tr></tbody></table><p>Spark was a natural-language micro-app builder. Density is too low — and it is closing — so it is <strong>not</strong> a standalone page. If you already have a Spark, export the repo from the workbench (<code>…</code> → <strong>Create repository</strong>) before 2026-08-31. Official: <a href="https://github.blog/changelog/2026-08-04-upcoming-deprecation-of-github-spark-on-github-com/" target="_blank" rel="noreferrer">Spark deprecation</a>.</p><h3 id="quick-decision-which-surface" tabindex="-1">Quick decision: which surface? <a class="header-anchor" href="#quick-decision-which-surface" aria-label="Permalink to &quot;Quick decision: which surface?&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What am I doing right now?</span></span>
<span class="line"><span>├── Writing / completing / refactoring in an editor</span></span>
<span class="line"><span>│   └── → IDE</span></span>
<span class="line"><span>│       ├── Next line / boilerplate          → Code completion (Tab)</span></span>
<span class="line"><span>│       ├── I only want to understand        → Chat Ask</span></span>
<span class="line"><span>│       ├── I know which files               → Chat Edit</span></span>
<span class="line"><span>│       └── I give the goal, you own the process → Chat Agent (local, has side effects)</span></span>
<span class="line"><span>├── The work lives on the command line (scripts, git, build failures, no IDE)</span></span>
<span class="line"><span>│   └── → Copilot CLI</span></span>
<span class="line"><span>│       ├── Multi-turn                       → \`copilot\`</span></span>
<span class="line"><span>│       └── One-shot in a script             → \`copilot -p &quot;...&quot;\`</span></span>
<span class="line"><span>├── I am already on github.com (this repo / this Issue / this PR)</span></span>
<span class="line"><span>│   └── → github.com</span></span>
<span class="line"><span>│       ├── Ask about this repo              → Copilot Chat</span></span>
<span class="line"><span>│       ├── Well-scoped and slow, I will not watch → Cloud agent</span></span>
<span class="line"><span>│       └── Review this PR                   → Code review</span></span>
<span class="line"><span>└── Direct several agents in parallel and stay out of the IDE</span></span>
<span class="line"><span>    └── → Copilot app (desktop)</span></span></code></pre></div><p>Three mix-ups to lock in now:</p><table tabindex="0"><thead><tr><th>Easy to confuse</th><th>Difference</th></tr></thead><tbody><tr><td>Chat <strong>Agent mode</strong> vs <strong>Cloud agent</strong></td><td>Agent mode runs on your machine. Cloud agent runs on GitHub (Actions-powered environment) and produces a branch / PR. <a href="https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent" target="_blank" rel="noreferrer">Official contrast</a>.</td></tr><tr><td>Standalone <strong><code>copilot</code> CLI</strong> vs <strong><code>gh copilot</code></strong></td><td>The former is a full agent and is <strong>generally available</strong>. The latter is <strong>retired</strong> (explain / suggest only).</td></tr><tr><td><strong>Copilot app</strong> vs <strong>IDE Chat</strong></td><td>The app is a desktop shell on top of Copilot CLI: parallel sessions, Issues / PRs, automations. IDE Chat stays inside the editor.</td></tr></tbody></table><p>More look-alikes live in the <a href="./copilot-glossary.html">Glossary</a>.</p><p>The mechanism that drives every later optimization: Copilot is <strong>not</strong> &quot;we trained a model on your repo.&quot; It <strong>retrieves and injects context on every request</strong>. &quot;Huge repo ⇒ Copilot knows it&quot; is false. &quot;Open the relevant files, then ask&quot; is what works.</p><h2 id="core-concepts-at-a-glance" tabindex="-1">Core concepts at a glance <a class="header-anchor" href="#core-concepts-at-a-glance" aria-label="Permalink to &quot;Core concepts at a glance&quot;">​</a></h2><p>See the <a href="./copilot-glossary.html">Glossary</a> for full definitions.</p><table tabindex="0"><thead><tr><th>Concept</th><th>One-line explanation</th><th>Where it appears</th></tr></thead><tbody><tr><td><strong>Four daily doors</strong></td><td>Completion, IDE Chat, CLI, Cloud agent</td><td>Every page</td></tr><tr><td><strong>Ask / Edit / Agent</strong></td><td>Three autonomy levels <strong>inside IDE Chat</strong></td><td>IDE</td></tr><tr><td><strong>Cloud agent</strong></td><td>Background agent on GitHub; paid plans; admin must enable it on Business / Enterprise</td><td>github.com / Issue / VS Code</td></tr><tr><td><strong>Copilot CLI</strong></td><td>Terminal agent (<code>copilot</code>). Not <code>gh copilot</code></td><td>Terminal</td></tr><tr><td><strong>Copilot app</strong></td><td>Desktop app for parallel agent sessions</td><td>Desktop</td></tr><tr><td><strong>Custom instructions</strong></td><td>Auto-attached project constraints</td><td>All surfaces</td></tr><tr><td><strong>Prompt files</strong></td><td><code>/name</code> reusable tasks</td><td>IDE Chat</td></tr><tr><td><strong>MCP</strong></td><td>Open protocol to external tools. Replaced GitHub App Extensions</td><td>All agentic surfaces</td></tr><tr><td><strong>Plugins / Skills</strong></td><td>Installable packs of agents, skills, hooks</td><td>CLI / Chat / app</td></tr><tr><td><strong>Spaces</strong></td><td>Named context pack (repos + files + notes)</td><td>github.com / Chat</td></tr><tr><td><strong>AI credits</strong></td><td>Usage unit for Chat, CLI, agents, review</td><td>Billing</td></tr></tbody></table><h2 id="which-page-to-open" tabindex="-1">Which page to open <a class="header-anchor" href="#which-page-to-open" aria-label="Permalink to &quot;Which page to open&quot;">​</a></h2><p>This set follows <a href="https://diataxis.fr/" target="_blank" rel="noreferrer">Diataxis</a>. <strong>Do not read the cheatsheet as a tutorial:</strong></p><table tabindex="0"><thead><tr><th>Page</th><th>Quadrant</th><th>Open it when</th></tr></thead><tbody><tr><td><a href="./copilot.html">Getting started</a></td><td>Tutorial</td><td>First time: install → sign in → four daily doors → persist project conventions</td></tr><tr><td><a href="./copilot-cookbook.html">Cookbook</a></td><td>How-to</td><td>You already know the basics and want a copy-paste recipe</td></tr><tr><td><a href="./copilot-cheatsheet.html">Cheatsheet</a></td><td>Reference</td><td>Look up a keybinding, slash command, setting, CLI flag, or plan quota</td></tr><tr><td><a href="./copilot-glossary.html">Glossary</a></td><td>Explanation</td><td>You hit an unknown term, or you suspect a blog post is stale</td></tr></tbody></table><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><h3 id="stage-1-make-it-work" tabindex="-1">Stage 1: Make it work <a class="header-anchor" href="#stage-1-make-it-work" aria-label="Permalink to &quot;Stage 1: Make it work&quot;">​</a></h3><p><strong>Goal</strong>: install, sign in, and understand retrieval-based context.</p><table tabindex="0"><thead><tr><th>Step</th><th>Content</th><th>Link</th></tr></thead><tbody><tr><td>1</td><td>Pick a plan — there is a free tier</td><td><a href="./copilot.html">Tutorial · Step 0</a></td></tr><tr><td>2</td><td>Install the IDE extension and sign in; install the CLI only if you need the terminal agent</td><td><a href="./copilot.html">Tutorial · Step 1</a></td></tr><tr><td>3</td><td>Learn retrieval-based context injection — every later optimization depends on it</td><td><a href="./copilot.html">Tutorial · Step 2</a></td></tr></tbody></table><h3 id="stage-2-pick-the-right-door" tabindex="-1">Stage 2: Pick the right door <a class="header-anchor" href="#stage-2-pick-the-right-door" aria-label="Permalink to &quot;Stage 2: Pick the right door&quot;">​</a></h3><p><strong>Goal</strong>: stop paying the &quot;wrong surface&quot; tax.</p><table tabindex="0"><thead><tr><th>Step</th><th>Content</th><th>Link</th></tr></thead><tbody><tr><td>4</td><td>IDE vs github.com vs CLI vs cloud vs desktop</td><td>Decision tree above; <a href="./copilot.html">Tutorial · Step 3</a></td></tr><tr><td>5</td><td>Build muscle memory for Ask / Edit / Agent</td><td><a href="./copilot-glossary.html">Glossary · three modes</a></td></tr><tr><td>6</td><td>Feed context with <code>@</code> and <code>#</code></td><td><a href="./copilot-cheatsheet.html">Cheatsheet · chat participants</a></td></tr></tbody></table><h3 id="stage-3-stop-repeating-yourself" tabindex="-1">Stage 3: Stop repeating yourself <a class="header-anchor" href="#stage-3-stop-repeating-yourself" aria-label="Permalink to &quot;Stage 3: Stop repeating yourself&quot;">​</a></h3><p><strong>Goal</strong>: write conventions once.</p><table tabindex="0"><thead><tr><th>Step</th><th>Content</th><th>Link</th></tr></thead><tbody><tr><td>7</td><td>Write <code>.github/copilot-instructions.md</code></td><td><a href="./copilot-cookbook.html">Cookbook · project conventions</a></td></tr><tr><td>8</td><td>Reuse prompt files for shaped tasks</td><td><a href="./copilot-cookbook.html">Cookbook · prompt files</a></td></tr><tr><td>9</td><td>Attach MCP servers for databases and internal APIs</td><td><a href="./copilot-glossary.html">Glossary · MCP</a></td></tr></tbody></table><h3 id="stage-4-scale-and-stay-safe" tabindex="-1">Stage 4: Scale and stay safe <a class="header-anchor" href="#stage-4-scale-and-stay-safe" aria-label="Permalink to &quot;Stage 4: Scale and stay safe&quot;">​</a></h3><p><strong>Goal</strong>: delegate, then review.</p><table tabindex="0"><thead><tr><th>Step</th><th>Content</th><th>Link</th></tr></thead><tbody><tr><td>10</td><td>Delegate to Cloud agent; write a task description with hard edges</td><td><a href="./copilot-cookbook.html">Cookbook · Delegating to the cloud</a></td></tr><tr><td>11</td><td>Review anything that touches auth, SQL string building, crypto, or payments</td><td><a href="./copilot.html">Tutorial · Step 6</a></td></tr></tbody></table><h2 id="feature-quick-reference" tabindex="-1">Feature quick reference <a class="header-anchor" href="#feature-quick-reference" aria-label="Permalink to &quot;Feature quick reference&quot;">​</a></h2><h3 id="assistive-you-stay-in-the-loop" tabindex="-1">Assistive (you stay in the loop) <a class="header-anchor" href="#assistive-you-stay-in-the-loop" aria-label="Permalink to &quot;Assistive (you stay in the loop)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Purpose</th><th>Doc</th></tr></thead><tbody><tr><td>Inline suggestions</td><td>Next line / boilerplate; Tab to accept</td><td><a href="./copilot.html">Tutorial</a></td></tr><tr><td>IDE Chat · Ask</td><td>Explain, compare, plan — never edits</td><td><a href="./copilot-glossary.html">Glossary</a></td></tr><tr><td>IDE Chat · Edit</td><td>Diffs on files you name</td><td><a href="./copilot-cookbook.html">Cookbook</a></td></tr><tr><td>Copilot Chat on github.com</td><td>Ask about a repo / Issue / PR without opening an IDE</td><td><a href="https://docs.github.com/en/copilot/how-tos/copilot-on-github/chat-with-copilot/chat-in-github" target="_blank" rel="noreferrer">Ask questions in GitHub</a></td></tr><tr><td>PR summaries</td><td>AI summary of a pull request</td><td><a href="https://docs.github.com/en/copilot/how-tos/copilot-on-github/copilot-for-github-tasks/create-a-pr-summary" target="_blank" rel="noreferrer">Create a PR summary</a></td></tr><tr><td>GitHub Desktop</td><td>Commit message from the diff</td><td><a href="https://docs.github.com/en/copilot/get-started/features" target="_blank" rel="noreferrer">Features</a></td></tr></tbody></table><h3 id="agentic-it-can-run-without-you-watching" tabindex="-1">Agentic (it can run without you watching) <a class="header-anchor" href="#agentic-it-can-run-without-you-watching" aria-label="Permalink to &quot;Agentic (it can run without you watching)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Purpose</th><th>Doc</th></tr></thead><tbody><tr><td>IDE Agent mode</td><td>Local multi-step edits + commands you approve</td><td><a href="./copilot-cookbook.html">Cookbook</a></td></tr><tr><td>Copilot CLI</td><td>Terminal agent; interactive or <code>copilot -p</code></td><td><a href="./copilot-cheatsheet.html">Cheatsheet · CLI</a> · <a href="https://docs.github.com/en/copilot/concepts/agents/copilot-cli/about-copilot-cli" target="_blank" rel="noreferrer">About CLI</a></td></tr><tr><td>Cloud agent</td><td>Research / plan / branch / optional PR on GitHub</td><td><a href="./copilot-cookbook.html">Cookbook</a> · <a href="https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent" target="_blank" rel="noreferrer">About cloud agent</a></td></tr><tr><td>Copilot app</td><td>Desktop: parallel sessions, Issues / PRs, automations</td><td><a href="https://docs.github.com/en/copilot/concepts/agents/github-copilot-app" target="_blank" rel="noreferrer">About the Copilot app</a></td></tr><tr><td>Code review</td><td>AI review comments on a PR</td><td><a href="https://docs.github.com/en/copilot/how-tos/use-copilot-agents/request-a-code-review/use-code-review" target="_blank" rel="noreferrer">Code review</a></td></tr></tbody></table><h3 id="customization-cuts-across-every-door" tabindex="-1">Customization (cuts across every door) <a class="header-anchor" href="#customization-cuts-across-every-door" aria-label="Permalink to &quot;Customization (cuts across every door)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Feature</th><th>Purpose</th><th>Doc</th></tr></thead><tbody><tr><td>Custom instructions</td><td>Write once, attach every turn</td><td><a href="./copilot-cheatsheet.html">Cheatsheet</a></td></tr><tr><td>Prompt files</td><td><code>/name</code> reusable tasks</td><td><a href="./copilot-cookbook.html">Cookbook</a></td></tr><tr><td>MCP</td><td>External tools and data</td><td><a href="./copilot-glossary.html">Glossary</a></td></tr><tr><td>Skills / Plugins</td><td>Specialized packs</td><td><a href="./copilot-glossary.html">Glossary</a></td></tr><tr><td>Spaces</td><td>Named context pack</td><td><a href="./copilot-glossary.html">Glossary</a></td></tr></tbody></table><h2 id="currency-warnings" tabindex="-1">Currency warnings <a class="header-anchor" href="#currency-warnings" aria-label="Permalink to &quot;Currency warnings&quot;">​</a></h2><p>Copilot moves fast. Old tutorials (including our previous single file) are full of dead syntax:</p><ul><li><strong>Copilot Workspace</strong> (GitHub Next technical preview) <strong>sunset on 2025-05-30</strong>. &quot;Issue → plan → PR&quot; now lives on <strong>Cloud agent</strong>.</li><li><strong>GitHub App Copilot Extensions sunset on 2025-11-10</strong>. Official replacement: MCP. VS Code <strong>client-side</strong> Chat extensions are unaffected.</li><li><strong>GitHub Spark</strong> no longer accepts new users or new apps (<strong>2026-08-04</strong>). Existing users can export until <strong>2026-08-31</strong>. Deployed apps keep running. Do not write new Spark tutorials.</li><li><code>@workspace</code>, <code>#editor</code>, <code>#git</code>, <code>#vscodeAPI</code> are <strong>off the official list</strong>. Codebase retrieval is a tool; Agent mode calls it.</li><li>What used to be called <strong>&quot;coding agent&quot; is now cloud agent</strong>.</li><li><strong><code>gh copilot</code> (the GitHub CLI extension) is officially retired.</strong> Use standalone <code>copilot</code>.</li><li>Copilot CLI is <strong>generally available</strong> (since <a href="https://github.blog/changelog/2026-02-25-github-copilot-cli-is-now-generally-available/" target="_blank" rel="noreferrer">2026-02-25</a>). Pages that still say &quot;public preview&quot; are stale.</li><li>Copilot is <strong>not available on GitHub Enterprise Server</strong>.</li><li>Enterprise needs <strong>GitHub Enterprise Cloud</strong>. Business and Enterprise differ mainly in AI-credit pool and admin controls — numbers are in <a href="./copilot-cheatsheet.html">Cheatsheet · Plan comparison</a>.</li></ul><p>The full retired / renamed list is in <a href="./copilot-glossary.html">Glossary · Retired or renamed concepts</a>.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://docs.github.com/en/copilot" target="_blank" rel="noreferrer">GitHub Copilot documentation</a></li><li><a href="https://docs.github.com/en/copilot/get-started/features" target="_blank" rel="noreferrer">GitHub Copilot features</a></li><li><a href="https://code.visualstudio.com/docs/copilot/overview" target="_blank" rel="noreferrer">VS Code Copilot documentation</a></li><li><a href="./copilot-cheatsheet.html">Cheatsheet · High-quality sources</a> — sources ranked by trust; also the evidence base for this set</li></ul><blockquote><p><strong>Evidence rule</strong>: the Chinese <code>docs.github.com</code> tree is incomplete and lags. Paths like <code>docs.github.com/zh/enterprise-cloud@latest/...</code> are widely dead. Verify facts on <code>docs.github.com/en/copilot/...</code>.</p></blockquote>`,47)])])}const m=e(n,[["render",r]]);export{f as __pageData,m as default};
